"use client";
import { useId, useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";
export function ComparisonSlider({ before, after, beforeLabel = "Before", afterLabel = "After", className }: { before: ReactNode; after: ReactNode; beforeLabel?: string; afterLabel?: string; className?: string }): React.JSX.Element {
  const [position,setPosition]=useState(50); const id=useId();
  return <div data-slot="comparison-slider" className={cn("w-full",className)}><div className="relative aspect-[4/3] overflow-hidden rounded-2xl border border-border"><div className="absolute inset-0">{before}</div><div className="absolute inset-0" style={{clipPath:`inset(0 ${100-position}% 0 0)`}}>{after}</div><span className="absolute bottom-4 left-4 rounded-md bg-background px-3 py-1 text-xs shadow-sm">{afterLabel}</span><span className="absolute right-4 bottom-4 rounded-md bg-background px-3 py-1 text-xs shadow-sm">{beforeLabel}</span><div aria-hidden="true" className="pointer-events-none absolute inset-y-0 w-px bg-foreground" style={{left:`${position}%`}}><span className="absolute top-1/2 left-1/2 grid size-10 -translate-x-1/2 -translate-y-1/2 place-items-center rounded-full border border-border bg-background text-sm shadow-md">↔</span></div></div><label htmlFor={id} className="mt-4 flex items-center gap-4 text-xs text-muted-foreground"><span>Compare views</span><input id={id} aria-label="Comparison position" type="range" min={0} max={100} value={position} onChange={event=>setPosition(Number(event.target.value))} className="min-w-0 flex-1 accent-current"/><span className="w-10 text-right tabular-nums">{position}%</span></label></div>;
}
